def triangle_minimum_total(triangle):
    dp = list(triangle[-1])
    for r in range(len(triangle) - 2, -1, -1):
        row = triangle[r]
        dp = [row[j] + min(dp[j], dp[j + 1]) for j in range(len(row))]
    return dp[0]
